<script>
const bindUpload=row=>{const btn=row.querySelector('.earning-upload');btn.addEventListener('click',async()=>{const file=row.querySelector('.earning-file').files[0],status=row.querySelector('.upload-status');if(!file){status.textContent='Choose an image first';return;}const data=new FormData();data.append('image',file);data.append('_csrf',<?=json_encode(csrf_token())?>);status.textContent='Uploading…';try{const response=await fetch(<?=json_encode(url('admin/upload.php'))?>,{method:'POST',body:data}),json=await response.json();if(!response.ok)throw Error(json.error||'Upload failed');row.querySelector('.earning-image-url').value=json.url;status.textContent='Uploaded';}catch(error){status.textContent=error.message;}});const remove=row.querySelector('.remove-earning-card');if(remove)remove.addEventListener('click',()=>row.remove());};
document.querySelectorAll('.earning-admin-row').forEach(bindUpload);
document.getElementById('add-earning-card').addEventListener('click',()=>{const row=document.getElementById('earning-card-template').content.firstElementChild.cloneNode(true);document.getElementById('earning-cards').appendChild(row);bindUpload(row);row.querySelector('input').focus();});
</script></body></html>